  1	import { useRef, useMemo, useState, useEffect, useCallback } from "react";
  2	import { useMemoizedFn } from "ahooks";
  3	import { IconSend, IconPlayerStop, IconChevronDown, IconPlus } from "@tabler/icons-react";
  4	import { Button } from "@/components/ui/button";
  5	import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
  6	import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
  7	import { ActionMenu } from "../ActionMenu";
  8	import { SlashCommandMenu } from "../SlashCommandMenu";
  9	import { FilePickerMenu } from "../FilePickerMenu";
 10	import { MediaThumbnail } from "../MediaThumbnail";
 11	import { MediaPreviewModal } from "../MediaPreviewModal";
 12	import { BottomToolbar } from "../BottomToolbar";
 13	import { StreamingConfirmDialog } from "../StreamingConfirmDialog";
 14	import { ThinkingButton } from "../ThinkingButton";
 15	import { PlanModeButton } from "../PlanModeButton";
 16	import { useChatStore, useSettingsStore, getModelById, getModelsForMedia } from "@/stores";
 17	import { bridge, Events } from "@/services";
 18	import { Content } from "@/lib/content";
 19	import { cn } from "@/lib/utils";
 20	import { useSlashMenu, findActiveToken } from "./hooks/useSlashMenu";
 21	import { useFilePicker } from "./hooks/useFilePicker";
 22	import { useMediaUpload } from "./hooks/useMediaUpload";
 23	import { useClickOutside } from "./hooks/useClickOutside";
 24	import { useInputHistory } from "./hooks/useInputHistory";
 25	import { computeMentionInsert } from "./utils";
 26	
 27	interface InputAreaProps {
 28	  onAuthAction?: () => void;
 29	}
 30	
 31	export function InputArea({ onAuthAction }: InputAreaProps) {
 32	  const textareaRef = useRef<HTMLTextAreaElement>(null);
 33	  const menuRef = useRef<HTMLDivElement>(null);
 34	  const [cursorPos, setCursorPos] = useState(0);
 35	  const [previewMedia, setPreviewMedia] = useState<string | null>(null);
 36	
 37	  const { isStreaming, sendMessage, abort, draftMedia, removeDraftMedia, hasProcessingMedia, getMediaInConversation, pendingInput, queue, planMode } = useChatStore();
 38	  const inputDraft = useChatStore(s => s.inputDraft);
 39	  const setInputDraft = useChatStore(s => s.setInputDraft);
 40	  const { currentModel, thinkingEnabled, updateModel, toggleThinking, models, extensionConfig, getCurrentThinkingMode } = useSettingsStore();
 41	
 42	  const isProcessing = hasProcessingMedia();
 43	  const thinkingMode = getCurrentThinkingMode();
 44	
 45	  const [showPlanModeConfirm, setShowPlanModeConfirm] = useState(false);
 46	
 47	  const handleTogglePlanMode = () => {
 48	    // Turning OFF during streaming needs confirmation — user may want next turn, not current
 49	    if (planMode && isStreaming) {
 50	      setShowPlanModeConfirm(true);
 51	      return;
 52	    }
 53	    const newState = !planMode;
 54	    useChatStore.setState({ planMode: newState }); // optimistic
 55	    bridge.setPlanMode(newState);
 56	  };
 57	
 58	  const handleConfirmExitPlanMode = () => {
 59	    useChatStore.setState({ planMode: false });
 60	    bridge.setPlanMode(false);
 61	    setShowPlanModeConfirm(false);
 62	  };
 63	
 64	  const mediaReq = useMemo(() => {
 65	    const media = getMediaInConversation();
 66	    return { image: media.hasImage, video: media.hasVideo };
 67	  }, [getMediaInConversation, draftMedia]);
 68	
 69	  const availableModels = useMemo(() => getModelsForMedia(models, mediaReq), [models, mediaReq]);
 70	  const currentModelConfig = getModelById(models, currentModel);
 71	
 72	  // Auto-switch model if current model doesn't support required media
 73	  useEffect(() => {
 74	    if (!mediaReq.image && !mediaReq.video) {
 75	      return;
 76	    }
 77	    const isCurrentModelValid = availableModels.some((m) => m.id === currentModel);
 78	    if (isCurrentModelValid) {
 79	      return;
 80	    }
 81	    if (availableModels.length > 0) {
 82	      updateModel(availableModels[0].id);
 83	    }
 84	  }, [mediaReq.image, mediaReq.video, currentModel, availableModels, updateModel]);
 85	
 86	  // Restore pending input
 87	  useEffect(() => {
 88	    if (!pendingInput || isStreaming) {
 89	      return;
 90	    }
 91	
 92	    // 只在输入框为空时恢复
 93	    if (inputDraft.trim()) {
 94	      return;
 95	    }
 96	
 97	    const textContent = Content.getText(pendingInput.content);
 98	    if (textContent) {
 99	      setInputDraft(textContent);
100	      setTimeout(() => {
101	        textareaRef.current?.focus();
102	        adjustHeight();
103	      }, 0);
104	    }
105	  }, [pendingInput, isStreaming]);
106	
107	  const activeToken = useMemo(() => findActiveToken(inputDraft, cursorPos), [inputDraft, cursorPos]);
108	
109	  const { canAddMedia, handlePaste, handlePickMedia } = useMediaUpload();
110	
111	  const adjustHeight = useMemoizedFn(() => {
112	    const ta = textareaRef.current;
113	    if (ta) {
114	      ta.style.height = "auto";
115	      ta.style.height = `${Math.min(ta.scrollHeight, 140)}px`;
116	    }
117	  });
118	
119	  const {
120	    handleKey: handleHistoryKey,
121	    add: addToHistory,
122	    reset: resetHistoryIndex,
123	  } = useInputHistory({
124	    text: inputDraft,
125	    setText: setInputDraft,
126	    onHeightChange: () => setTimeout(adjustHeight, 0),
127	  });
128	
129	  const clearInput = useMemoizedFn(() => {
130	    setInputDraft("");
131	    setCursorPos(0);
132	    setTimeout(adjustHeight, 0);
133	  });
134	
135	  const removeActiveToken = useMemoizedFn(() => {
136	    if (!activeToken) return;
137	    const newText = inputDraft.slice(0, activeToken.start) + inputDraft.slice(cursorPos);
138	    const newCursorPos = activeToken.start;
139	    setInputDraft(newText);
140	    setCursorPos(newCursorPos);
141	    setTimeout(() => {
142	      textareaRef.current?.setSelectionRange(newCursorPos, newCursorPos);
143	      adjustHeight();
144	    }, 0);
145	  });
146	
147	  const handleSend = useMemoizedFn(() => {
148	    if (isProcessing || (!inputDraft.trim() && draftMedia.length === 0)) {
149	      return;
150	    }
151	
152	    addToHistory(inputDraft);
153	    sendMessage(inputDraft);
154	    clearInput();
155	  });
156	
157	  const handleSlashCommand = useMemoizedFn((name: string) => {
158	    sendMessage(`/${name}`);
159	    clearInput();
160	  });
161	
162	  const applyMention = useMemoizedFn((filePath: string) => {
163	    const { newText, newCursorPos } = computeMentionInsert({
164	      text: inputDraft,
165	      cursorPos,
166	      filePath,
167	      activeToken,
168	      isAppend: false,
169	    });
170	
171	    setInputDraft(newText);
172	    setCursorPos(newCursorPos);
173	    setTimeout(() => {
174	      textareaRef.current?.setSelectionRange(newCursorPos, newCursorPos);
175	      textareaRef.current?.focus();
176	      adjustHeight();
177	    }, 0);
178	  });
179	
180	  const {
181	    showSlashMenu,
182	    filteredCommands,
183	    selectedIndex: slashSelectedIndex,
184	    setSelectedIndex: setSlashSelectedIndex,
185	    handleSlashMenuKey,
186	    resetSlashMenu,
187	  } = useSlashMenu(activeToken, handleSlashCommand, removeActiveToken);
188	
189	  const {
190	    showFileMenu,
191	    filePickerMode,
192	    folderPath,
193	    fileItems,
194	    selectedIndex: fileSelectedIndex,
195	    isLoading: isFileLoading,
196	    showMediaOption,
197	    setSelectedIndex: setFileSelectedIndex,
198	    setFilePickerMode,
199	    setFolderPath,
200	    handleFileMenuKey,
201	    resetFilePicker,
202	  } = useFilePicker(activeToken, applyMention, handlePickMedia, removeActiveToken);
203	
204	  const closeMenus = useCallback(() => {
205	    if (showSlashMenu || showFileMenu) {
206	      removeActiveToken();
207	    }
208	  }, [showSlashMenu, showFileMenu, removeActiveToken]);
209	
210	  useClickOutside([textareaRef, menuRef], showSlashMenu || showFileMenu, closeMenus);
211	
212	  useEffect(() => {
213	    resetSlashMenu();
214	  }, [showSlashMenu, resetSlashMenu]);
215	
216	  useEffect(() => {
217	    if (!showFileMenu) {
218	      resetFilePicker();
219	    }
220	  }, [showFileMenu, resetFilePicker]);
221	
222	  useEffect(() => {
223	    const unsub = bridge.on<{ mention: string }>(Events.InsertMention, ({ mention }) => {
224	      const current = useChatStore.getState().inputDraft;
225	      setInputDraft(current + mention + " ");
226	
227	      setTimeout(() => {
228	        textareaRef.current?.focus();
229	        adjustHeight();
230	      }, 0);
231	    });
232	
233	    return unsub;
234	  }, [adjustHeight]);
235	
236	  const handleKeyDown = useMemoizedFn((e: React.KeyboardEvent<HTMLTextAreaElement>) => {
237	    if (e.nativeEvent.isComposing) {
238	      return;
239	    }
240	
241	    if (handleSlashMenuKey(e)) {
242	      return;
243	    }
244	
245	    if (handleFileMenuKey(e)) {
246	      return;
247	    }
248	
249	    if (handleHistoryKey(e)) {
250	      return;
251	    }
252	
253	    if (extensionConfig.useCtrlEnterToSend) {
254	      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
255	        e.preventDefault();
256	        handleSend();
257	      }
258	    } else {
259	      if (e.key === "Enter" && !e.shiftKey) {
260	        e.preventDefault();
261	        handleSend();
262	      }
263	    }
264	  });
265	
266	  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
267	    setInputDraft(e.target.value);
268	    setCursorPos(e.target.selectionStart);
269	    resetHistoryIndex();
270	    setTimeout(adjustHeight, 0);
271	  };
272	
273	  const handleSelect = () => {
274	    setCursorPos(textareaRef.current?.selectionStart ?? 0);
275	  };
276	
277	  const handleAddButtonClick = useMemoizedFn(() => {
278	    const newText = inputDraft + "@";
279	    setInputDraft(newText);
280	    setCursorPos(newText.length);
281	    setTimeout(() => {
282	      textareaRef.current?.focus();
283	      textareaRef.current?.setSelectionRange(newText.length, newText.length);
284	      adjustHeight();
285	    }, 0);
286	  });
287	
288	  const hasModels = availableModels.length > 0;
289	  const canSend = (inputDraft.trim() || draftMedia.length > 0) && !isProcessing;
290	
291	  return (
292	    <div className="p-2 pt-0! flex flex-col min-h-0">
293	      <BottomToolbar />
294	      <div className="relative shrink-0">
295	        {showSlashMenu && filteredCommands.length > 0 && (
296	          <div ref={menuRef} className="absolute bottom-full left-0 right-0 mb-2 z-10">
297	            <SlashCommandMenu
298	              commands={filteredCommands}
299	              query={activeToken?.query || ""}
300	              selectedIndex={slashSelectedIndex}
301	              onSelect={handleSlashCommand}
302	              onHover={setSlashSelectedIndex}
303	            />
304	          </div>
305	        )}
306	
307	        {showFileMenu && (
308	          <div ref={menuRef} className="absolute bottom-full left-0 right-0 mb-2 z-10">
309	            <FilePickerMenu
310	              mode={filePickerMode}
311	              items={fileItems}
312	              currentPath={folderPath}
313	              selectedIndex={fileSelectedIndex}
314	              isLoading={isFileLoading}
315	              showMediaOption={showMediaOption}
316	              onSelectMedia={handlePickMedia}
317	              onSwitchToFolder={() => {
318	                setFilePickerMode("folder");
319	                setFolderPath("");
320	                setFileSelectedIndex(0);
321	              }}
322	              onSwitchToSearch={() => {
323	                setFilePickerMode("search");
324	                setFolderPath("");
325	                setFileSelectedIndex(0);
326	              }}
327	              onSelectItem={(item) => applyMention(item.path)}
328	              onNavigateUp={() => {
329	                setFolderPath(folderPath.split("/").slice(0, -1).join("/"));
330	                setFileSelectedIndex(0);
331	              }}
332	              onNavigateInto={(item) => {
333	                setFilePickerMode("folder");
334	                setFolderPath(item.path);
335	                setFileSelectedIndex(0);
336	              }}
337	              onHover={setFileSelectedIndex}
338	            />
339	          </div>
340	        )}
341	
342	        <div className="border border-input rounded-md overflow-hidden">
343	          {draftMedia.length > 0 && (
344	            <div className="flex gap-2 p-2 overflow-x-auto">
345	              {draftMedia.map((item) => (
346	                <MediaThumbnail
347	                  key={item.id}
348	                  src={item.dataUri}
349	                  size="sm"
350	                  onClick={item.dataUri ? () => setPreviewMedia(item.dataUri!) : undefined}
351	                  onRemove={() => removeDraftMedia(item.id)}
352	                />
353	              ))}
354	            </div>
355	          )}
356	
357	          <textarea
358	            ref={textareaRef}
359	            value={inputDraft}
360	            onChange={handleChange}
361	            onKeyDown={handleKeyDown}
362	            onSelect={handleSelect}
363	            onPaste={handlePaste}
364	            placeholder={isStreaming ? "Add a follow-up..." : "Ask Consilium... (/ commands · @ files · Alt+K code)"}
365	            className={cn(
366	              "w-full min-h-12 max-h-35 px-2.5 py-1.5 text-xs leading-relaxed",
367	              "bg-transparent resize-none outline-none border-none overflow-y-auto",
368	              "placeholder:text-muted-foreground",
369	            )}
370	          />
371	
372	          <div className="flex items-center justify-between px-1.5 pb-1.5">
373	            <div className="flex items-center gap-1.5 min-w-0 flex-1">
374	              <DropdownMenu>
375	                <DropdownMenuTrigger asChild>
376	                  <Button
377	                    variant="ghost"
378	                    size="xs"
379	                    className="gap-0.5 text-accent-foreground border-0! h-6 px-1.5 min-w-0 max-w-[calc(100%-4rem)]"
380	                    disabled={isStreaming || !hasModels}
381	                  >
382	                    <span className="text-xs truncate block">{currentModelConfig?.name || "No models available"}</span>
383	                    {hasModels && <IconChevronDown className="size-3.5 shrink-0" />}
384	                  </Button>
385	                </DropdownMenuTrigger>
386	                <DropdownMenuContent className="w-52!" align="start">
387	                  {availableModels.map((model) => (
388	                    <DropdownMenuItem
389	                      key={model.id}
390	                      onClick={() => updateModel(model.id)}
391	                      className={cn("text-xs px-3 py-1.5 cursor-pointer", currentModel === model.id && "bg-accent")}
392	                    >
393	                      {model.name}
394	                    </DropdownMenuItem>
395	                  ))}
396	                </DropdownMenuContent>
397	              </DropdownMenu>
398	
399	              <ThinkingButton mode={thinkingMode} enabled={thinkingEnabled} disabled={isStreaming} onToggle={toggleThinking} />
400	              <PlanModeButton active={planMode} onToggle={handleTogglePlanMode} />
401	            </div>
402	
403	            <div className="flex items-center gap-2 shrink-0">
404	              <Tooltip>
405	                <TooltipTrigger asChild>
406	                  <Button variant="ghost" size="icon-xs" onClick={handleAddButtonClick} className="text-muted-foreground">
407	                    <IconPlus className="size-3.5" />
408	                  </Button>
409	                </TooltipTrigger>
410	                <TooltipContent>Add files or media</TooltipContent>
411	              </Tooltip>
412	
413	              <ActionMenu onAuthAction={onAuthAction} />
414	
415	              {isStreaming ? (
416	                <Button variant="destructive" size="icon-xs" onClick={abort}>
417	                  <IconPlayerStop className="size-3.5" />
418	                </Button>
419	              ) : (
420	                <Button variant="default" size="icon-xs" onClick={handleSend} disabled={!canSend}>
421	                  <IconSend className="size-3.5" />
422	                </Button>
423	              )}
424	            </div>
425	          </div>
426	        </div>
427	      </div>
428	      <MediaPreviewModal src={previewMedia} onClose={() => setPreviewMedia(null)} />
429	      <StreamingConfirmDialog
430	        open={showPlanModeConfirm}
431	        onOpenChange={setShowPlanModeConfirm}
432	        title="Exit Plan Mode"
433	        description="The agent is still working. Exiting plan mode now will affect the current turn. Are you sure you want to exit plan mode immediately?"
434	        confirmLabel="Exit Now"
435	        onConfirm={handleConfirmExitPlanMode}
436	      />
437	    </div>
438	  );
439	}
